<?php
declare(strict_types=1);
date_default_timezone_set('Asia/Karachi');
require_once __DIR__ . '/../app/bootstrap.php';
require_once __DIR__ . '/../app/billing_helpers.php';
$user=require_role('admin','receptionist'); $pdo=db(); $error=''; $flash=(string)($_SESSION['sd_notifications_flash']??''); unset($_SESSION['sd_notifications_flash']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf($_POST['_csrf']??null)) $error='Your security token expired. Refresh and try again.';
    elseif((string)($_POST['action']??'')==='run_notifications'){
        try { $result=sd_notifications_run($pdo); $_SESSION['sd_notifications_flash']='Reminder check completed. Attempts: '.(int)$result['considered'].', accepted by provider: '.(int)$result['sent'].', failed: '.(int)$result['failed'].', skipped: '.(int)$result['skipped'].'. See delivery log below. Delivery may be skipped until mail/SMS is configured.'; header('Location: notifications-center.php'); exit; }
        catch(Throwable $e){error_log('SalonDiva notifications error: '.$e->getMessage());$error='Could not run notification checks. Confirm the Payment & Notifications migration was installed.';}
    }
}
try{
    $next=$pdo->query("SELECT a.id,a.booking_code,a.starts_at,a.service_name_snapshot,c.name customer_name,c.email customer_email,c.phone customer_phone,u.name stylist_name FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN users u ON u.id=a.stylist_user_id WHERE a.status='confirmed' AND a.starts_at>=NOW() AND a.starts_at<=DATE_ADD(NOW(),INTERVAL 7 DAY) ORDER BY a.starts_at LIMIT 100")->fetchAll();
    $overdue=$pdo->query("SELECT i.id,i.invoice_number,i.due_date,i.total_amount,c.name customer_name,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id=i.id),0) paid_amount FROM invoices i JOIN customers c ON c.id=i.customer_id WHERE i.status IN ('open','partially_paid') AND i.due_date<CURDATE() ORDER BY i.due_date LIMIT 100")->fetchAll();
    $low=$pdo->query('SELECT id,name,quantity_on_hand,reorder_level,unit FROM inventory_items WHERE is_active=1 AND quantity_on_hand<=reorder_level ORDER BY quantity_on_hand,name LIMIT 100')->fetchAll();
    $logs=$pdo->query('SELECT * FROM notification_logs ORDER BY attempted_at DESC,id DESC LIMIT 100')->fetchAll();
}catch(Throwable $e){error_log('SalonDiva notifications list error: '.$e->getMessage());http_response_code(500);echo '<!doctype html><meta charset="utf-8"><h1>Notifications setup is incomplete</h1><p>Run database/payments_notifications_migration.sql after the Appointment Booking and Calendar & Analytics migrations, then refresh.</p>';exit;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications & Reminders · SalonDiva</title><style>
:root{--ink:#321d2a;--pink:#c52f63;--bg:#fff6f9;--line:#ead8e1;--muted:#806c77;--cream:#fffdf9;--green:#e3f5e8;--red:#fbe4e8;--gold:#fff1ce}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,Segoe UI,sans-serif}.wrap{max-width:1280px;margin:24px auto;padding:0 14px}.shell{background:var(--cream);border:1px solid var(--line);border-radius:20px;padding:clamp(14px,2.5vw,26px)}.brand{font-weight:850;color:var(--pink)}h1{margin:.25rem 0}h2{margin:0 0 12px;font-size:1.15rem}.muted,.hint{color:var(--muted)}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.btn{display:inline-block;background:var(--pink);color:#fff;padding:9px 12px;border-radius:9px;text-decoration:none;font-weight:700;border:0;cursor:pointer}.btn.light{background:#f5e5ec;color:var(--ink)}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:15px;margin-top:15px}.two{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}.alert{padding:11px;border-radius:9px;margin:12px 0;background:var(--green)}.alert.error{background:var(--red)}.notice{padding:11px;border-radius:9px;background:var(--gold);margin:12px 0}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:650px}td,th{text-align:left;padding:9px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#fbf0f4}.pill{padding:3px 7px;border-radius:99px;background:#f5e5ec}.pill.failed{background:var(--red)}.pill.skipped{background:var(--gold)}@media(max-width:600px){h1{font-size:24px}}
</style></head><body><main class="wrap"><div class="shell"><div class="brand">SalonDiva</div><h1>Notifications & reminders</h1><p class="muted">Review upcoming appointments, overdue balances, low stock, and delivery logs. Run a check now or schedule the PHP script to run automatically.</p><div class="nav"><a class="btn light" href="dashboard.php">Dashboard</a><a class="btn light" href="payments.php">Payments & invoices</a><a class="btn light" href="appointments.php">Appointments</a><a class="btn light" href="inventory.php">Inventory</a></div><?php if($flash!==''): ?><div class="alert"><?=sd_bill_h($flash)?></div><?php endif; ?><?php if($error!==''): ?><div class="alert error"><?=sd_bill_h($error)?></div><?php endif; ?><div class="notice"><strong>Delivery setup:</strong> Email requires <code>SALONDIVA_MAIL_FROM</code> and a working PHP mail transport. SMS requires <code>SALONDIVA_TWILIO_SID</code>, <code>SALONDIVA_TWILIO_TOKEN</code>, <code>SALONDIVA_TWILIO_FROM</code>, and PHP cURL. The log distinguishes sent/accepted, failed, and skipped attempts.</div><section class="panel"><h2>Run reminder check</h2><p>The check covers confirmed appointments in the next 24 hours, overdue invoices, and active inventory items at/below reorder level. Successfully sent events are deduplicated so clicking again should not resend the same reminder.</p><form method="post"><input type="hidden" name="_csrf" value="<?=sd_bill_h(csrf_token())?>"><input type="hidden" name="action" value="run_notifications"><button class="btn" type="submit">Run notifications now</button></form></section><div class="two"><section class="panel"><h2>Upcoming appointments (7 days)</h2><div class="tablewrap"><table><thead><tr><th>Date/time</th><th>Customer</th><th>Service</th><th>Stylist</th></tr></thead><tbody><?php foreach($next as $a): ?><tr><td><?=sd_bill_h(date('D d M H:i',strtotime((string)$a['starts_at'])))?><br><?=sd_bill_h((string)$a['booking_code'])?></td><td><?=sd_bill_h((string)$a['customer_name'])?><br><span class="hint"><?=sd_bill_h((string)($a['customer_email']??''))?></span></td><td><?=sd_bill_h((string)$a['service_name_snapshot'])?></td><td><?=sd_bill_h((string)$a['stylist_name'])?></td></tr><?php endforeach; ?><?php if(!$next): ?><tr><td colspan="4">No confirmed appointments in the next 7 days.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><h2>Overdue invoices</h2><div class="tablewrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Due date</th><th>Balance</th></tr></thead><tbody><?php foreach($overdue as $i): $balance=max(0,(float)$i['total_amount']-(float)$i['paid_amount']); if($balance<0.01) continue; ?><tr><td><a href="payments.php?view=<?=(int)$i['id']?>"><?=sd_bill_h((string)$i['invoice_number'])?></a></td><td><?=sd_bill_h((string)$i['customer_name'])?></td><td><?=sd_bill_h((string)$i['due_date'])?></td><td>PKR <?=number_format($balance,2)?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$overdue): ?><p class="muted">No overdue invoices found.</p><?php endif; ?></section></div><section class="panel"><h2>Low-stock alerts</h2><div class="tablewrap"><table><thead><tr><th>Item</th><th>Available</th><th>Reorder level</th></tr></thead><tbody><?php foreach($low as $i): ?><tr><td><?=sd_bill_h((string)$i['name'])?></td><td><span class="pill"><?=number_format((float)$i['quantity_on_hand'],3)?> <?=sd_bill_h((string)$i['unit'])?></span></td><td><?=number_format((float)$i['reorder_level'],3)?></td></tr><?php endforeach; ?><?php if(!$low): ?><tr><td colspan="3">No active inventory items at or below their reorder level.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel"><h2>Recent notification attempts</h2><div class="tablewrap"><table><thead><tr><th>Attempted</th><th>Event</th><th>Recipient</th><th>Channel</th><th>Status</th><th>Result</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?=sd_bill_h((string)$l['attempted_at'])?></td><td><?=sd_bill_h(ucwords(str_replace('_',' ',(string)$l['event_type'])))?><br><span class="hint"><?=sd_bill_h((string)$l['entity_type'])?> #<?=(int)$l['entity_id']?></span></td><td><?=sd_bill_h((string)$l['recipient'])?><br><span class="hint"><?=sd_bill_h((string)$l['recipient_type'])?></span></td><td><?=sd_bill_h(strtoupper((string)$l['channel']))?></td><td><span class="pill <?=sd_bill_h((string)$l['status'])?>"><?=sd_bill_h(ucfirst((string)$l['status']))?></span></td><td><?=sd_bill_h((string)($l['result_message']??''))?></td></tr><?php endforeach; ?><?php if(!$logs): ?><tr><td colspan="6">No notification attempts yet. Click Run notifications now.</td></tr><?php endif; ?></tbody></table></div></section></div></main></body></html>
